function [hd] = vscmg_rate(tm, fr, nz, k_c)
%VSCMG_RATE  The VSCMG rotor's momentum rate [N m]: tm less the uncompensated friction (compensation k_c) plus the noise nz.
%   tm: real[1] (passed a plain number)
%   fr: real[1] (passed a plain number)
%   nz: real[1] (passed a plain number)
%   k_c: real[1] (passed a plain number)
%   returns hd: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    hd = 0;
    hd = ((tm - asils.models.wheelcomp.uncompensated(fr, k_c)) + nz);
end
